type Need {
  item: Str,
  qty: Int,
}

fn is_positive(s: Str) -> Bool {
  if s.is_empty() {
    return false
  }
  if not s.chars().all(fn(c) => "0123456789".contains(c)) {
    return false
  }
  return s.to_int().unwrap_or(0) > 0
}

fn parse_need(part: Str) -> Option[Need] {
  let kv = part.split(":")
  if kv.len() != 2 {
    return None
  }
  let item = kv.get_or(0, "")
  let qty_text = kv.get_or(1, "")
  if item.is_empty() or not is_positive(qty_text) {
    return None
  }
  return Some(Need { item: item, qty: qty_text.to_int().unwrap_or(0) })
}

fn parse_needs(order: Str) -> Option[List[Need]] {
  let parts = order.split(" ")
  if parts.len() != 2 {
    return None
  }
  if parts.get_or(0, "").is_empty() {
    return None
  }
  var needs: List[Need] = []
  for item_text in parts.get_or(1, "").split(",") {
    let parsed = parse_need(item_text)
    if parsed.is_none() {
      return None
    }
    needs = needs.push(parsed.unwrap_or(Need { item: "", qty: 0 }))
  }
  return Some(needs)
}

pub fn inventory(orders: List[Str], stock: Map[Str, Int]) -> Result[List[Str], Str] {
  let empty_ids: List[Str] = []
  let empty_needs: List[Need] = []
  var filled: List[Str] = empty_ids
  var left: Map[Str, Int] = stock
  for order in orders {
    let id = order.split(" ").get_or(0, "")
    let parsed = parse_needs(order)
    if parsed.is_none() {
      return Err("bad order {id}")
    }
    let needs = parsed.unwrap_or(empty_needs)
    var fits = true
    var trial: Map[Str, Int] = left
    for nd in needs {
      if not left.has(nd.item) {
        return Err("bad order {id}")
      }
      let have = trial.get(nd.item).unwrap_or(0)
      if have < nd.qty {
        fits = false
      } else {
        trial = trial.set(nd.item, have - nd.qty)
      }
    }
    if fits {
      left = trial
      filled = filled.push(id)
    }
  }
  return Ok(filled)
}
